import gurobipy as gp
from gurobipy import GRB
I = list(range(68))
A = {0: 11, 1: 8, 2: 19, 3: 9, 4: 5, 5: 8, 6: 5.65, 7: 11, 8: 4.93, 9: 7, 10: 7, 11: 8, 12: 1.72, 13: 2, 14: 7, 15: 8, 16: 2, 17: 2, 18: 1.7, 19: 15, 20: 9, 21: 8, 22: 7, 23: 11, 24: 11, 25: 11, 26: 16, 27: 16, 28: 3.7, 29: 3.65, 30: 8, 31: 6, 32: 11, 33: 15, 34: 8, 35: 11, 36: 11, 37: 5, 38: 5.78, 39: 11, 40: 13, 41: 3.79, 42: 9, 43: 7, 44: 7, 45: 9, 46: 8, 47: 8, 48: 11, 49: 12, 50: 8, 51: 9, 52: 14, 53: 9, 54: 8, 55: 5.87, 56: 5.91, 57: 11, 58: 18, 59: 9, 60: 4, 61: 12, 62: 5.74, 63: 4, 64: 8, 65: 1.85, 66: 6, 67: 11}
d = {0: 1357, 1: 1363, 2: 1269, 3: 6500, 4: 6335, 5: 1283, 6: 27327, 7: 25600, 8: 264, 9: 14, 10: 1484, 11: 13124, 12: 123, 13: 1430, 14: 130, 15: 14, 16: 293, 17: 6770, 18: 1325, 19: 1377, 20: 139, 21: 1350, 22: 138, 23: 122, 24: 6577, 25: 1455, 26: 72, 27: 135, 28: 6531, 29: 26650, 30: 27115, 31: 12486, 32: 12367, 33: 6194, 34: 14307, 35: 6321, 36: 13833, 37: 144944, 38: 6319, 39: 13849, 40: 6875, 41: 29273, 42: 1207, 43: 62890, 44: 14465, 45: 25467, 46: 24105, 47: 25594, 48: 1229, 49: 1459, 50: 13071, 51: 13056, 52: 6170, 53: 24746, 54: 27118, 55: 29149, 56: 1459, 57: 136, 58: 130, 59: 6720, 60: 14932, 61: 25913, 62: 27066, 63: 7453, 64: 142, 65: 270, 66: 1418, 67: 28189}
I_inv = {0: 5000, 1: 5000, 2: 5000, 3: 25000, 4: 25000, 5: 5000, 6: 100000, 7: 100000, 8: 1000, 9: 50, 10: 5000, 11: 50000, 12: 500, 13: 5000, 14: 500, 15: 50, 16: 1000, 17: 25000, 18: 5000, 19: 5000, 20: 500, 21: 5000, 22: 500, 23: 500, 24: 25000, 25: 5000, 26: 250, 27: 500, 28: 25000, 29: 100000, 30: 100000, 31: 50000, 32: 50000, 33: 25000, 34: 50000, 35: 25000, 36: 50000, 37: 500000, 38: 25000, 39: 50000, 40: 25000, 41: 100000, 42: 5000, 43: 250000, 44: 50000, 45: 100000, 46: 100000, 47: 100000, 48: 5000, 49: 5000, 50: 50000, 51: 50000, 52: 25000, 53: 100000, 54: 100000, 55: 100000, 56: 5000, 57: 500, 58: 500, 59: 25000, 60: 50000, 61: 100000, 62: 100000, 63: 25000, 64: 500, 65: 1000, 66: 5000, 67: 100000}
if not (set(A.keys()) == set(I) and set(d.keys()) == set(I) and (set(I_inv.keys()) == set(I))):
    raise ValueError('Missing data for some indices in A, d, or I_inv.')
m = gp.Model('Ecommerce_Fulfillment')
x_vars = m.addVars(I, lb=0, vtype=GRB.INTEGER, name='')
m.addConstrs((x_vars[i] <= d[i] for i in I), name='')
m.addConstrs((x_vars[i] <= I_inv[i] for i in I), name='')
m.setObjective(gp.quicksum((A[i] * x_vars[i] for i in I)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')